title: $:/core/modules/commands/inspect/handlers/crud/put_tiddler.js
type: application/javascript
module-type: mcp-handler

MCP tool handler: put_tiddler — create new tiddler or full-rewrite an
existing one. Without overwrite, an existing title triggers uniquify.

\*/

"use strict";

var shared = require("$:/core/modules/commands/inspect/handlers/shared.js");

module.exports = {
	"put_tiddler": function(args) {
		var denied = shared.checkWritable("put_tiddler");
		if(denied) return denied;
		var titleErr = shared.checkTitle(args.title, "put_tiddler");
		if(titleErr) return titleErr;
		var title = args.title,
			existingTiddler = $tw.wiki.getTiddler(title),
			creationFields = $tw.wiki.getCreationFields(),
			modificationFields = $tw.wiki.getModificationFields(),
			tiddler;
		if(existingTiddler && args.overwrite) {
			tiddler = new $tw.Tiddler(existingTiddler.fields, args.fields, modificationFields, {title: title});
		} else if(existingTiddler) {
			title = $tw.wiki.generateNewTitle(title);
			tiddler = new $tw.Tiddler(creationFields, args.fields, modificationFields, {title: title});
		} else {
			tiddler = new $tw.Tiddler(creationFields, args.fields, modificationFields, {title: title});
		}
		return shared.persistTiddler(tiddler, title, "saved");
	}
};

// MCP tool definition — advertised via mcp-handlers getToolDefinitions();
// write:true marks tools hidden in readonly mode.
module.exports["put_tiddler"].definition = {
	"description": "Create or update tiddler, persists to disk. overwrite=true replaces existing. WITHOUT overwrite: existing-title silently creates duplicate with uniquified title (e.g. 'MyTiddler 1') — does NOT error. Check response title; use overwrite=true or edit_tiddler when updating.",
	"inputSchema": {
		"type": "object",
		"properties": {
			"title": {
				"type": "string",
				"maxLength": 1024,
				"description": "Tiddler title (max 1024 chars)"
			},
			"fields": {
				"type": "object",
				"description": "Tiddler fields (text, tags, type, etc.)",
				"additionalProperties": true
			},
			"overwrite": {
				"type": "boolean",
				"default": false
			}
		},
		"required": [
			"title",
			"fields"
		]
	},
	"write": true
};
","type":"application/javascript","module-type":"mcp-handler"},"$:/core/modules/commands/inspect/handlers/crud/rename_tiddler.js":{"title":"$:/core/modules/commands/inspect/handlers/crud/rename_tiddler.js","text":"/*\
title: $:/core/modules/commands/inspect/handlers/crud/rename_tiddler.js
type: application/javascript
module-type: mcp-handler

MCP tool handler: rename_tiddler — write the new title, then unlink the
old file + store entry. Best-effort on the unlink (the new tiddler is
already in place).

\*/

"use strict";

var shared = require("$:/core/modules/commands/inspect/handlers/shared.js");

module.exports = {
	"rename_tiddler": function(args) {
		var denied = shared.checkWritable("rename_tiddler");
		if(denied) return denied;
		var fromErr = shared.checkTitle(args.from, "rename_tiddler");
		if(fromErr) return fromErr;
		var toErr = shared.checkTitle(args.to, "rename_tiddler");
		if(toErr) return toErr;
		if(args.from === args.to) {
			return shared.errorResult("rename_tiddler: from and to are identical: " + args.from);
		}
		var oldTiddler = $tw.wiki.getTiddler(args.from);
		if(!oldTiddler) {
			return shared.errorResult("Tiddler not found: " + args.from);
		}
		var bundledErr = shared.checkNotBundled(oldTiddler, "rename", args.from);
		if(bundledErr) return bundledErr;
		var oldFileInfo = $tw.boot.files && $tw.boot.files[args.from];
		if(oldFileInfo && /\.multids$/i.test(oldFileInfo.filepath)) {
			return shared.errorResult("Tiddler is bundled in a .multids file, cannot rename individually: " + args.from);
		}
		var existingTarget = $tw.wiki.getTiddler(args.to);
		if(existingTarget && !args.overwrite) {
			return shared.errorResult("Target tiddler already exists: " + args.to + " (pass overwrite=true to replace)");
		}
		// Build new tiddler with the new title. preserve_timestamps defaults
		// to true (housekeeping rename), set false to bump `modified`.
		var preserveTimestamps = args.preserve_timestamps !== false;
		var newTiddler = shared.buildTiddlerWithTimestamps(oldTiddler.fields, {title: args.to}, preserveTimestamps);
		// Persist the new tiddler (handles FSP path resolution, write, verify,
		// rollback). On failure the new file/store entry is rolled back and
		// `from` is left untouched.
		var result = shared.persistTiddler(newTiddler, args.to, "renamed-to");
		if(result && result.isError) {
			return result;
		}
		// Persistence seam (pear/engine mode): the host owns removal of the
		// old title — no files, no $tw.boot.files entries there.
		var removeHook = shared.getRemoveHook();
		if(removeHook) {
			removeHook(args.from);
			return shared.textResult("Tiddler renamed: " + args.from + " -> " + args.to);
		}
		// Remove the old tiddler from disk and store. Best-effort: if the
		// unlink fails we still report the rename a success since the new
		// tiddler is in place; only stderr-warn.
		if(oldFileInfo) {
			try {
				$tw.utils.deleteTiddlerFile(oldFileInfo, function(err) {
					if(err) {
						process.stderr.write("[tw-mcp] rename_tiddler: error removing old file " + oldFileInfo.filepath + ": " + err + "\n");
					}
				});
			} catch(e) {
				process.stderr.write("[tw-mcp] rename_tiddler: exception removing old file " + oldFileInfo.filepath + ": " + e.message + "\n");
			}
			delete $tw.boot.files[args.from];
		}
		$tw.wiki.deleteTiddler(args.from);
		var newPath = $tw.boot.files[args.to] && $tw.boot.files[args.to].filepath;
		return shared.textResult("Tiddler renamed: " + args.from + " -> " + args.to + "\n" +
			"old: " + (oldFileInfo ? oldFileInfo.filepath : "(no file)") + "\n" +
			"new: " + (newPath || "(no file)"));
	}
};

// MCP tool definition — advertised via mcp-handlers getToolDefinitions();
// write:true marks tools hidden in readonly mode.
module.exports["rename_tiddler"].definition = {
	"description": "Rename a tiddler: updates title field + moves on-disk file via FSP rules + removes the old file (and .meta sidecar if present). Cross-references inside other tiddlers are NOT touched (use replace_in_tiddlers). preserve_timestamps=true (default) keeps the original `modified` field; set false to bump it. WITHOUT overwrite: errors if `to` exists. Refuses bundled plugin/theme/language tiddlers and .multids entries.",
	"inputSchema": {
		"type": "object",
		"properties": {
			"from": {
				"type": "string",
				"maxLength": 1024,
				"description": "Current tiddler title"
			},
			"to": {
				"type": "string",
				"maxLength": 1024,
				"description": "New tiddler title"
			},
			"overwrite": {
				"type": "boolean",
				"default": false,
				"description": "If true, replace an existing tiddler at `to`"
			},
			"preserve_timestamps": {
				"type": "boolean",
				"default": true,
				"description": "If true (default), keep the original `modified` field. Set false to set `modified` to now."
			}
		},
		"required": [
			"from",
			"to"
		]
	},
	"write": true
};
","type":"application/javascript","module-type":"mcp-handler"},"$:/core/modules/commands/inspect/handlers/crud/replace_in_tiddlers.js":{"title":"$:/core/modules/commands/inspect/handlers/crud/replace_in_tiddlers.js","text":"/*\
title: $:/core/modules/commands/inspect/handlers/crud/replace_in_tiddlers.js
type: application/javascript
module-type: mcp-handler

MCP tool handler: replace_in_tiddlers — bulk find+replace across many
tiddlers. Multiple {pattern, replacement} rules per call, per-rule flags;
dry_run=true by default — output groups by title with diff lines.

\*/

"use strict";

var shared = require("$:/core/modules/commands/inspect/handlers/shared.js");
var crudShared = require("$:/core/modules/commands/inspect/handlers/crud/_shared.js");

module.exports = {
	"replace_in_tiddlers": function(args) {
		var denied = shared.checkWritable("replace_in_tiddlers");
		if(denied) return denied;
		if(!args.rules || !Array.isArray(args.rules) || args.rules.length === 0) {
			return shared.errorResult("replace_in_tiddlers: 'rules' must be a non-empty array of {pattern, replacement} objects");
		}
		var fields = (args.fields && args.fields.length > 0) ? args.fields : ["text", "caption", "list", "tags"];
		var dryRun = args.dry_run !== false;
		var maxTiddlers = args.max_tiddlers || 100;
		var maxReplacementsTotal = args.max_replacements_total || 1000;
		var compiledRules = [];
		for(var i = 0; i < args.rules.length; i++) {
			var rule = args.rules[i];
			if(typeof rule.pattern !== "string" || rule.pattern.length === 0) {
				return shared.errorResult("replace_in_tiddlers: rule " + i + " missing or empty 'pattern'");
			}
			if(typeof rule.replacement !== "string") {
				return shared.errorResult("replace_in_tiddlers: rule " + i + " 'replacement' must be a string");
			}
			if(rule.pattern.length > shared.MAX_FILTER_LENGTH) {
				return shared.errorResult("replace_in_tiddlers: rule " + i + " pattern too long (max " + shared.MAX_FILTER_LENGTH + ")");
			}
			var compiled = shared.compileSearchRegex({
				pattern: rule.pattern,
				regexp: !!rule.regexp,
				words: !!rule.words,
				caseSensitive: !!rule.case_sensitive,
				global: true
			});
			if(compiled.error) {
				return shared.errorResult("replace_in_tiddlers: rule " + i + " invalid regex: " + compiled.error);
			}
			compiledRules.push({matcher: compiled.matcher, replacement: rule.replacement});
		}
		var scoped = shared.scopedTitles(args);
		if(scoped.errorResult) return scoped.errorResult;
		var sourceTitles = scoped.titles;
		// Scan: per tiddler, per listed field, per line. Replacements within
		// a line are sequential across rules (rule2 sees rule1's output) so
		// chained renames work like sed -e ... -e ....
		var modified = [];
		var totalReplacements = 0;
		var truncated = false;
		for(var ti = 0; ti < sourceTitles.length && !truncated; ti++) {
			var title = sourceTitles[ti];
			var tiddler = $tw.wiki.getTiddler(title);
			if(!tiddler) continue;
			var perFieldChanges = [];
			var newFieldValues = {};
			var tiddlerReplacements = 0;
			for(var fi = 0; fi < fields.length; fi++) {
				var field = fields[fi];
				var rawValue = tiddler.fields[field];
				var isArrayField = Array.isArray(rawValue);
				var value;
				if(isArrayField) {
					value = $tw.utils.stringifyList(rawValue);
				} else if(typeof rawValue === "string") {
					value = rawValue;
				} else {
					continue;
				}
				var lines = value.split(/\r?\n/);
				var lineDiffs = [];
				var newLines = [];
				var fieldChanged = false;
				for(var li = 0; li < lines.length; li++) {
					var before = lines[li];
					var after = before;
					var lineReplacements = 0;
					for(var ri = 0; ri < compiledRules.length; ri++) {
						var cr = compiledRules[ri];
						var matches = after.match(cr.matcher);
						if(matches) {
							lineReplacements += matches.length;
							after = after.replace(cr.matcher, cr.replacement);
						}
					}
					if(after !== before) {
						lineDiffs.push({lineNum: li + 1, before: before, after: after, count: lineReplacements});
						tiddlerReplacements += lineReplacements;
						fieldChanged = true;
					}
					newLines.push(after);
				}
				if(fieldChanged) {
					var newValue = newLines.join("\n");
					newFieldValues[field] = isArrayField ? $tw.utils.parseStringArray(newValue) : newValue;
					perFieldChanges.push({field: field, isArrayField: isArrayField, lineDiffs: lineDiffs});
				}
			}
			if(perFieldChanges.length === 0) continue;
			if(totalReplacements + tiddlerReplacements > maxReplacementsTotal) {
				truncated = true;
				break;
			}
			modified.push({
				title: title,
				newFieldValues: newFieldValues,
				perFieldChanges: perFieldChanges,
				tiddlerReplacements: tiddlerReplacements
			});
			totalReplacements += tiddlerReplacements;
			if(modified.length >= maxTiddlers) {
				truncated = true;
				break;
			}
		}
		if(modified.length === 0) {
			return shared.textResult("(no matches)");
		}
		if(dryRun) {
			return shared.textResult(crudShared.formatReplaceDryRun(modified, totalReplacements, truncated));
		}
		return shared.textResult(crudShared.applyReplacements(modified, totalReplacements, truncated));
	}
};

// MCP tool definition — advertised via mcp-handlers getToolDefinitions();
// write:true marks tools hidden in readonly mode.
module.exports["replace_in_tiddlers"].definition = {
	"description": "Bulk per-line find+replace across tiddlers. Dry-run output (dry_run=true default): title header, '  - <n>#<hash>: before' then '  + <n>#<hash>: after' per change (text field anchor; other fields 'field:L<n>'). Footer 'DRY RUN: N replacements across M tiddlers' + 'Call again with dry_run=false to apply'. Apply output: '<N> tiddlers modified, <M> replacements' + failure list. Empty: '(no matches)'. Defaults: fields=['text','caption','list','tags'] (tags/list serialised via stringifyList, parsed back on write), case-insensitive literal. Rules applied sequentially per line. Regex compiled with g flag (all matches per line); replacement supports JS backrefs $1..$9, $&, $$. Caps: max_tiddlers=100, max_replacements_total=1000.",
	"inputSchema": {
		"type": "object",
		"properties": {
			"rules": {
				"type": "array",
				"description": "Array of {pattern, replacement, regexp?, case_sensitive?, words?} objects",
				"items": {
					"type": "object",
					"properties": {
						"pattern": {
							"type": "string",
							"description": "Find pattern (literal by default; regex when regexp=true)"
						},
						"replacement": {
							"type": "string",
							"description": "Replacement string. When regexp=true supports $1..$9, $&, $$."
						},
						"regexp": {
							"type": "boolean",
							"default": false
						},
						"case_sensitive": {
							"type": "boolean",
							"default": false
						},
						"words": {
							"type": "boolean",
							"default": false,
							"description": "Wrap pattern with \\b boundaries"
						}
					},
					"required": [
						"pattern",
						"replacement"
					]
				}
			},
			"filter": {
				"type": "string",
				"description": "TW filter scope; default '[all[tiddlers]!is[system]]' or '[all[tiddlers]]' when include_system"
			},
			"include_system": {
				"type": "boolean",
				"default": false
			},
			"fields": {
				"type": "array",
				"items": {
					"type": "string"
				},
				"description": "Fields to scan; default ['text','caption','list','tags']"
			},
			"dry_run": {
				"type": "boolean",
				"default": true,
				"description": "Preview only; nothing written. Set false to apply."
			},
			"max_tiddlers": {
				"type": "number",
				"default": 100
			},
			"max_replacements_total": {
				"type": "number",
				"default": 1000
			}
		},
		"required": [
			"rules"
		]
	},
	"write": true
};
